// @name Form showcase
// @background #0f172a
// @refresh 3600
// Every kind of field a JSX scene can have, on one touch screen: text with a
// placeholder, a password with show/hide, a number with its number pad and a
// stepper, a textarea, a select box with a long list, buttons, chips, a
// switch, a slider, and the form scrolling under the keyboard on the screen.
// Save keeps the values with frameos.remember, so they come back after a
// restart; Reset starts over. What is typed and not saved yet is remembered
// too ('draft'): a frame rendered on its server, or one short of memory,
// starts this module afresh between taps.

const CITIES = [
  'Amsterdam', 'Athens', 'Berlin', 'Brussels', 'Copenhagen', 'Dublin', 'Helsinki', 'Lisbon', 'London',
  'Madrid', 'Oslo', 'Paris', 'Prague', 'Reykjavik', 'Riga', 'Rome', 'Stockholm', 'Tallinn', 'Vienna',
  'Vilnius', 'Warsaw', 'Zurich',
]
const SIZES = ['Small', 'Medium', 'Large']
const TOPPINGS = ['Olives', 'Basil', 'Chili', 'Mushrooms', 'Pineapple']

const blank = () => ({
  name: '', password: '', seconds: '60', city: '', size: 'Medium',
  toppings: ['Basil'], dark: true, brightness: 70,
  notes: 'A textarea wraps its lines.\nUp and Down on a keyboard move a line.\nA finger or the wheel scrolls it.\nFour\nFive\nSix',
})

// Each value is a signal: a tap or a key runs only the components that read
// what it changed (a field, its line in Live values, the preview card), not get().
const form = Object.fromEntries(Object.entries(blank()).map(([key, value]) => [key, signal(value)]))
let loaded = false
const showPassword = signal(false)
const lastKey = signal('')
const savedAt = signal('')
const status = signal('')

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// The class strings of each look. Where high contrast puts a border on a box
// that sizes itself, its padding gives the border's width back.
const THEMES = {
  color: {
    page: 'bg-slate-900 text-white',
    header: 'border-b border-slate-800',
    side: 'border-l border-slate-800',
    muted: 'text-slate-400',
    value: 'text-white',
    label: 'text-slate-300',
    hint: 'text-slate-500',
    field: 'bg-slate-800 text-white focus:bg-slate-700 focus:border focus:border-sky-500 placeholder:text-slate-500',
    picked: 'bg-sky-600 text-white',
    pick: 'active:bg-slate-600',
    primary: 'px-5 bg-sky-500 text-white hover:bg-sky-400 active:bg-sky-600',
    secondary: 'px-5 bg-slate-800 text-slate-200 hover:bg-slate-700 active:bg-slate-600',
    segments: 'p-1 bg-slate-800',
    segOn: 'bg-sky-500 text-white',
    segOff: 'text-slate-300 active:bg-slate-700',
    chipOn: 'px-3 border bg-emerald-600 border-emerald-500 text-white',
    chipOff: 'px-3 border bg-slate-800 border-slate-700 text-slate-300 active:bg-slate-700',
    switchOn: 'p-1 bg-sky-500 justify-end',
    switchOff: 'p-1 bg-slate-700',
    knobOn: 'bg-white',
    knobOff: 'bg-white',
    track: 'bg-slate-700',
    fill: 'bg-sky-500',
    dark: { box: 'p-3 bg-slate-800', bar: 'py-3 border-t border-slate-800 bg-slate-800', title: 'text-white', text: 'text-slate-300', muted: 'text-slate-400' },
    light: { box: 'p-3 bg-amber-100', bar: 'py-3 border-t border-slate-800 bg-amber-100', title: 'text-amber-950', text: 'text-amber-900', muted: 'text-amber-900' },
  },
  high: {
    page: 'bg-white text-black',
    header: 'border-b-2 border-black',
    side: 'border-l-2 border-black',
    muted: 'text-black',
    value: 'text-black',
    label: 'text-black',
    hint: 'text-black',
    field: 'bg-white text-black border-2 border-black focus:border-4',
    picked: 'bg-black text-white',
    pick: '',
    primary: 'px-5 bg-black text-white',
    secondary: 'px-[18px] bg-white text-black border-2 border-black',
    segments: 'p-[2px] bg-white border-2 border-black',
    segOn: 'bg-black text-white',
    segOff: 'text-black',
    chipOn: 'px-[11px] border-2 bg-black border-black text-white',
    chipOff: 'px-[11px] border-2 bg-white border-black text-black',
    switchOn: 'p-1 bg-black justify-end',
    switchOff: 'p-[2px] bg-white border-2 border-black',
    knobOn: 'bg-white',
    knobOff: 'bg-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    dark: { box: 'p-3 bg-black', bar: 'pt-[11px] pb-3 border-t-2 border-black bg-black', title: 'text-white', text: 'text-white', muted: 'text-white' },
    light: { box: 'p-[10px] bg-white border-2 border-black', bar: 'pt-[11px] pb-3 border-t-2 border-black bg-white', title: 'text-black', text: 'text-black', muted: 'text-black' },
  },
}
// The look of this render, picked in get().
let look = THEMES.color

// The form's values as one object, as they are remembered.
const values = () => Object.fromEntries(Object.entries(form).map(([key, value]) => [key, value.peek()]))
const fill = (next) => {
  for (const key of Object.keys(form)) form[key].value = next[key]
}

const load = () => {
  if (loaded) return
  loaded = true
  const draft = frameos.recall('draft')
  const kept = draft && typeof draft === 'object' ? draft : frameos.recall('form')
  if (kept && typeof kept === 'object') fill({ ...blank(), ...kept })
  showPassword.value = frameos.recall('showPassword') === true
  const at = frameos.recall('savedAt')
  if (typeof at === 'string') savedAt.value = at
}

const set = (key, value) => {
  form[key].value = value
  status.value = ''
  frameos.remember('draft', values())
}

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n))

const save = () => {
  frameos.remember('form', values())
  frameos.remember('draft', null)
  savedAt.value = new Date().toTimeString().slice(0, 5)
  frameos.remember('savedAt', savedAt.peek())
  status.value = `Saved at ${savedAt.peek()}`
}

const reset = () => {
  fill(blank())
  frameos.remember('form', null)
  frameos.remember('draft', null)
  frameos.remember('savedAt', null)
  savedAt.value = ''
  status.value = 'Reset'
}

const setBrightness = (e) => { set('brightness', clamp(Math.round((e.localX / e.width) * 100), 0, 100)) }
const toggleTopping = (name) => {
  const toppings = form.toppings.peek()
  set('toppings', toppings.includes(name) ? toppings.filter((x) => x !== name) : [...toppings, name])
}
const stepSeconds = (by) => { set('seconds', String(clamp((parseInt(form.seconds.peek(), 10) || 0) + by, 0, 3600))) }

const Row = ({ label, hint, children }) => (
  <div className="flex flex-col gap-1">
    <div className="flex items-end justify-between">
      <span className={`shrink-0 whitespace-nowrap text-sm font-semibold ${look.label}`}>{label}</span>
      {hint ? <span className={`text-xs truncate ${look.hint}`}>{hint}</span> : null}
    </div>
    {children}
  </div>
)

// The frame's font has no check mark glyph: draw it, in the text color.
const Check = () => (
  <svg viewBox="0 0 24 24" className="w-4 h-4 mr-1">
    <path d="M5 12.5l4.5 4.5L19 7.5" fill="none" stroke="currentColor" strokeWidth="3"
      strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

const Button = ({ label, onClick, primary }) => (
  <div
    className={`h-11 rounded-lg flex items-center justify-center text-lg font-semibold ${primary ? look.primary : look.secondary}`}
    onClick={onClick}>
    {label}
  </div>
)

// The parts a value shows in, each memo()'d and reading its signals. They take
// the look (and a field's classes) as props, so a new theme runs them again.
const Status = memo(({ look }) => (
  <span className={`text-sm truncate ${look.muted}`}>
    {status.value || (lastKey.value ? `Last key: ${lastKey.value}` : 'Tap a field to type')}
  </span>
))

const NameRow = memo(({ field }) => (
  <Row label="Name" hint="hold a key for accents">
    <input className={field} value={form.name.value} placeholder="Who is this frame for?"
      onChange={(e) => { set('name', e.target.value) }}
      onKeyDown={(e) => { lastKey.value = e.key; if (e.key === 'Enter') save() }} />
  </Row>
))

const PasswordRow = memo(({ field }) => {
  const shown = showPassword.value
  return (
    <Row label="Wi-Fi password" hint={shown ? 'shown' : 'hidden'}>
      <div className="flex gap-2">
        <input type={shown ? 'text' : 'password'} className={`${field} flex-1`}
          value={form.password.value} placeholder="Secret"
          onChange={(e) => { set('password', e.target.value) }} />
        <Button label={shown ? 'Hide' : 'Show'} onClick={() => { showPassword.value = !shown; frameos.remember('showPassword', !shown || null) }} />
      </div>
    </Row>
  )
})

const SecondsRow = memo(({ field }) => (
  <Row label="Seconds per picture" hint="number pad">
    <div className="flex gap-2">
      <Button label="−" onClick={() => { stepSeconds(-10) }} />
      <input type="number" className={`${field} flex-1 text-center`} value={form.seconds.value}
        onChange={(e) => { set('seconds', e.target.value) }} />
      <Button label="+" onClick={() => { stepSeconds(10) }} />
    </div>
  </Row>
))

const CityRow = memo(({ field, look }) => {
  const city = form.city.value
  return (
    <Row label="City" hint="a list that scrolls">
      <select className={field} value={city} placeholder="Choose a city"
        onChange={(e) => { set('city', e.target.value) }}>
        {CITIES.map((c) => <option value={c} className={`rounded ${city === c ? look.picked : look.pick}`}>{c}</option>)}
      </select>
    </Row>
  )
})

const SizeRow = memo(({ look }) => {
  const size = form.size.value
  return (
    <Row label="Size" hint="buttons">
      <div className={`flex rounded-lg gap-1 ${look.segments}`}>
        {SIZES.map((s) => (
          <div
            className={`flex-1 h-9 rounded-md flex items-center justify-center text-sm whitespace-nowrap font-semibold ${size === s ? look.segOn : look.segOff}`}
            onClick={() => { set('size', s) }}>
            {s}
          </div>
        ))}
      </div>
    </Row>
  )
})

const ToppingsRow = memo(({ look }) => {
  const toppings = form.toppings.value
  return (
    <Row label="Toppings" hint="pick any">
      <div className="flex flex-wrap gap-2">
        {TOPPINGS.map((name) => (
          <div
            className={`h-9 rounded-full flex items-center text-base ${toppings.includes(name) ? look.chipOn : look.chipOff}`}
            onClick={() => { toggleTopping(name) }}>
            {toppings.includes(name) ? <Check /> : null}
            <span>{name}</span>
          </div>
        ))}
      </div>
    </Row>
  )
})

const DarkRow = memo(({ look }) => {
  const dark = form.dark.value
  return (
    <div className="flex items-center justify-between h-11" onClick={() => { set('dark', !dark) }}>
      <span className="text-lg">Dark mode</span>
      <div className={`w-12 h-7 rounded-full flex ${dark ? look.switchOn : look.switchOff}`}>
        <div className={`w-5 h-5 rounded-full ${dark ? look.knobOn : look.knobOff}`} />
      </div>
    </div>
  )
})

const BrightnessRow = memo(({ look }) => {
  const brightness = form.brightness.value
  return (
    <Row label="Brightness" hint={`${brightness}% · drag`}>
      <div className="h-10 flex items-center" onPointerDown={setBrightness}
        onPointerMove={(e) => { if (e.buttons) setBrightness(e) }}>
        <div className={`h-3 w-full rounded-full flex ${look.track}`}>
          <div className={`h-full rounded-full w-[${brightness}%] ${look.fill}`} />
        </div>
      </div>
    </Row>
  )
})

const NotesRow = memo(({ field }) => (
  <Row label="Notes" hint="drag to scroll">
    <textarea className={`${field} h-28 py-2 leading-snug`} value={form.notes.value}
      placeholder="Anything else? The field wraps and scrolls."
      onChange={(e) => { set('notes', e.target.value) }} />
  </Row>
))

const SavedLine = memo(({ look }) => (
  <span className={`text-xs text-center ${look.hint}`}>
    {savedAt.value ? `Saved values come back after a restart (last ${savedAt.value}).` : 'Nothing saved yet.'}
  </span>
))

// Live values: a line each, so a change runs only its own line.
const SUMMARY = [
  ['Name', () => form.name.value || '—'],
  ['Password', () => (form.password.value ? '•'.repeat(form.password.value.length) : '—')],
  ['Seconds', () => form.seconds.value || '—'],
  ['City', () => form.city.value || '—'],
  ['Size', () => form.size.value],
  ['Toppings', () => (form.toppings.value.length ? form.toppings.value.join(', ') : 'none')],
  ['Dark mode', () => (form.dark.value ? 'on' : 'off')],
  ['Brightness', () => `${form.brightness.value}%`],
  ['Notes', () => (form.notes.value ? `${form.notes.value.length} chars` : '—')],
]
const Live = memo(({ i, look }) => (
  <div className="flex justify-between gap-3">
    <span className={`text-sm shrink-0 ${look.muted}`}>{SUMMARY[i][0]}</span>
    <span className={`text-sm truncate ${look.value}`}>{SUMMARY[i][1]()}</span>
  </div>
))

const Card = memo(({ look }) => {
  const card = form.dark.value ? look.dark : look.light
  return (
    <div className={`mt-auto rounded-lg ${card.box}`}>
      <div className={`text-xs ${card.muted}`}>Preview card</div>
      <div className={`text-lg font-bold truncate ${card.title}`}>
        {form.name.value || 'Your name'}
      </div>
      <div className={`text-sm truncate ${card.text}`}>
        {form.city.value || 'Somewhere'} · {form.size.value} · {form.seconds.value}s
      </div>
    </div>
  )
})

const Bar = memo(({ look }) => {
  const card = form.dark.value ? look.dark : look.light
  const toppings = form.toppings.value
  return (
    <div className={`shrink-0 flex items-center justify-between gap-3 px-5 ${card.bar}`}>
      <div className="flex flex-col min-w-0">
        <span className={`text-lg font-bold truncate ${card.title}`}>{form.name.value || 'Your name'}</span>
        <span className={`text-sm truncate ${card.text}`}>
          {form.city.value || 'Somewhere'} · {form.size.value} · {form.seconds.value}s · {form.brightness.value}%
        </span>
      </div>
      <span className={`text-xs shrink-0 ${card.muted}`}>
        {toppings.length ? toppings.join(', ') : 'no toppings'}
      </span>
    </div>
  )
})

export function get(app, context) {
  load()
  look = highContrast(app) ? THEMES.high : THEMES.color
  // The canvas this draws into, already turned with the frame (app.frame is
  // the panel's size before the turn).
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const W = context?.imageWidth ?? (turned ? app.frame.height : app.frame.width)
  const H = context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)
  // Stacked, the summary at the bottom, on a portrait screen and on one too
  // narrow for the side pane to leave the form about 420 px.
  const stacked = H > W || W < 720
  const field = `h-11 px-3 rounded-lg text-lg ${look.field}`

  return (
    <div className={`flex flex-col h-full ${look.page}`}>
      <div className={`flex items-center justify-between h-14 px-5 shrink-0 ${look.header}`}>
        <span className="text-xl font-bold">Form showcase</span>
        <Status look={look} />
      </div>

      <div className={`flex-1 flex ${stacked ? 'flex-col' : 'flex-row'}`}>
        <div className="flex-1 overflow-y-auto">
          <div className="flex flex-col gap-4 p-5">
            <NameRow field={field} />
            <PasswordRow field={field} />
            <SecondsRow field={field} />
            <CityRow field={field} look={look} />
            <SizeRow look={look} />
            <ToppingsRow look={look} />
            <DarkRow look={look} />
            <BrightnessRow look={look} />
            <NotesRow field={field} />

            <div className="flex gap-3 pt-1">
              <div className="flex-1">
                <Button label="Save" primary onClick={save} />
              </div>
              <Button label="Reset" onClick={reset} />
            </div>
            <SavedLine look={look} />
          </div>
        </div>

        {stacked ? null : (
        <div className={`w-72 shrink-0 p-5 flex flex-col gap-3 ${look.side}`}>
          <span className={`text-sm font-semibold uppercase ${look.muted}`}>Live values</span>
          {SUMMARY.map((_, i) => <Live i={i} look={look} />)}
          <Card look={look} />
        </div>
        )}
      </div>
      {stacked ? <Bar look={look} /> : null}
    </div>
  )
}
